import Link from 'next/link'; import type {Match} from '@/types/match'; import {formatDate} from '@/utils/formatDate';
const resultLabel={WIN:'勝利',DRAW:'引分',LOSE:'敗戦'} as const;
export function MatchCard({match}: {match:Match}){const home=match.homeAway==='HOME';return <Link className="match-card" href={`/matches/${match.matchId}`}><div className="card-top"><span>{match.competition} · {match.round}</span><span className={`badge ${match.result?.toLowerCase()??'scheduled'}`}>{match.result?resultLabel[match.result]:'開催予定'}</span></div><p className="date">{formatDate(match.date)}　{match.kickoffTime}</p><div className="scoreline"><span>{home?'鹿島アントラーズ':match.opponent.name}</span><strong>{match.score?`${home?match.score.kashima:match.score.opponent} － ${home?match.score.opponent:match.score.kashima}`:'VS'}</strong><span>{home?match.opponent.name:'鹿島アントラーズ'}</span></div><p className="venue">{match.homeAway} · {match.venue}</p></Link>}
